40. //==================================================================================================
41. // Constants
42. //==================================================================================================
43. 
44. // Use relaxed ordering for all atomic operations to mitigate synchronization overhead. It is safe
45. // to use this ordering semantics because Nanvix is a single-core system, and the kernel runs with
46. // interrupts disabled.
47. const ORDER: Ordering = Ordering::Relaxed;
48. 
49. //==================================================================================================
50. // Global Variables
51. //==================================================================================================
52. 
53. /// Physical memory manager storage.
54. static mut PHYS_MEMORY_MANAGER: MaybeUninit<PhysMemoryManager> = MaybeUninit::uninit();
55. 
56. /// Whether the physical memory manager has been initialized.
57. static PHYS_MEMORY_MANAGER_INIT: AtomicBool = AtomicBool::new(false);
58. 
59. //==================================================================================================
60. // Structures
61. //==================================================================================================
62. 
63. ///
64. /// # Description
65. ///
66. /// Physical memory manager.
67. ///
68. #[verus_verify]
69. pub struct PhysMemoryManager {
70.     upool: Upool,
71. }
72. 
73. //==================================================================================================
74. // Implementations
75. //==================================================================================================
76. 
77. #[verus_verify]
78. impl PhysMemoryManager {
79.     ///
80.     /// # Description
81.     ///
82.     /// Initializes the physical memory manager singleton.
83.     ///
84.     /// # Parameters
85.     ///
86.     /// - `upool`: User page pool.
87.     ///
88.     /// # Errors
89.     ///
90.     /// Returns `InvalidArgument` if the singleton has already been initialized.
91.     ///
92.     // TCB: bringing up the manager singleton writes a `MaybeUninit` static behind an
93.     // `AtomicBool` flag — raw-memory/atomics operations outside Verus's model. On success the
94.     // manager layer becomes ready (`phys_view().manager_ready`); the frame partition is
95.     // untouched. Listed in `verus-ai-logs/tcb-allowed.md`.
96.     #[verus_verify(external_body)]
97.     #[verus_spec(result =>
98.         ensures
99.             match result {
100.                 Ok(_) => crate::mm::phys::phys_view().manager_ready,
101.                 Err(_) => crate::mm::phys::phys_view().manager_ready,
102.             },
103.     )]
104.     pub(super) fn init(upool: Upool) -> Result<(), Error> {
105.         if unlikely(PHYS_MEMORY_MANAGER_INIT.load(ORDER)) {
106.             return Err(Error::new(
107.                 ErrorCode::InvalidArgument,
108.                 "physical memory manager already initialized",
109.             ));
110.         }
111. 
112.         // SAFETY: this happens during kernel initialization and no other threads are running.
113.         unsafe { PHYS_MEMORY_MANAGER.write(PhysMemoryManager { upool }) };
114.         PHYS_MEMORY_MANAGER_INIT.store(true, ORDER);
115.         Ok(())
116.     }
117. }
118. 
119. impl PhysMemoryManager {
120.     ///
121.     /// # Description
122.     ///
123.     /// Gets a mutable reference to the physical memory manager.
124.     ///
125.     /// # Panics
126.     ///
127.     /// Panics if the physical memory manager is not initialized.
128.     ///
129.     /// # Safety
130.     ///
131.     /// This function is unsafe because it returns a mutable reference to a global variable.
132.     ///
133.     /// The caller must ensure:
134.     ///
135.     /// - No other `&mut PhysMemoryManager` reference obtained from this function is live at the
136.     ///   same time (i.e., `&mut` references must not overlap). In practice this is guaranteed
137.     ///   because the kernel is single-threaded and runs with interrupts disabled, so no
138.     ///   re-entrant or concurrent call can alias the reference.
139.     ///
140.     pub unsafe fn get_mut<'a>() -> &'a mut PhysMemoryManager {
141.         if unlikely(!PHYS_MEMORY_MANAGER_INIT.load(ORDER)) {
142.             panic!("physical memory manager is not initialized");
143.         }
144. 
145.         // SAFETY: the physical memory manager has been initialized, so the value is valid.
146.         PHYS_MEMORY_MANAGER.assume_init_mut()
147.     }
148. }
149. 
150. #[verus_verify]
151. impl PhysMemoryManager {
152.     ///
153.     /// # Description
154.     ///
155.     /// Allocates user frames into caller-provided storage.
156.     ///
157.     /// The returned frames are not guaranteed to be physically contiguous.
158.     /// User allocations are gated by the kernel watermark: if fulfilling the request would
159.     /// leave fewer than `KERNEL_WATERMARK` free frames, the allocation is rejected.
160.     ///
161.     /// # Parameters
162.     ///
163.     /// - `count`: Number of frames to allocate.
164.     /// - `frames`: Mutable reference to a pre-allocated vector into which to store those
165.     ///   frames' addresses. It should have sufficient capacity for `count` entries.
166.     ///
167.     /// # Return Values
168.     ///
169.     /// Upon success, `Ok(())` is returned and `frames` is filled with `count` frames. Upon failure, an
170.     /// error is returned and any frames allocated by this call are dropped by truncating `frames`
171.     /// back to empty.
172.     ///
173.     #[verus_spec(result =>
174.         requires
175.             self.inv(),
176.             old(frames)@.len() == 0,
177.         ensures
178.             final(self).inv(),
179.             match result {
180.                 Ok(()) => {
181.                     &&& (count > 0 ==> old(self)@.user_alloc_ok(count as nat))
182.                     &&& final(frames)@.len() == count
183.                     &&& user_addr_set(final(frames)@).len() == count
184.                     &&& old(self)@.all_free(user_addr_set(final(frames)@))
185.                     &&& final(self)@ == old(self)@.book_all(user_addr_set(final(frames)@))
186.                 },
187.                 Err(_) => {
188.                     &&& final(self)@ == old(self)@
189.                     &&& final(frames)@.len() == 0
190.                 },
191.             },
192.     )]
193.     pub fn alloc_many_user_frames(
194.         &mut self,
195.         count: usize,
196.         frames: &mut Vec<UserFrame>,
197.     ) -> Result<(), Error> {
198.         proof_decl! {
199.             let ghost g_old = self@;
200.         }
201.         proof! {
202.             assert(g_old == old(self)@);
203.             assert(g_old.wf());
204.         }
205.         if !frames.is_empty() {
206.             let reason: &str = "frames vector is not empty";
207.             #[cfg(not(verus_keep_ghost))]
208.             error!("{reason}");
209.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
210.         }
211.         if frames.capacity() < count {
212.             let reason: &str = "frames vector has insufficient capacity";
213.             #[cfg(not(verus_keep_ghost))]
214.             error!("{reason}");
215.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
216.         }
217. 
218.         // A zero-sized allocation is trivially satisfied.
219.         if count == 0 {
220.             proof! {
221.                 lemma_user_addr_set_empty(frames@);
222.                 lemma_book_all_empty(g_old);
223.             }
224.             return Ok(());
225.         }
226. 
227.         Self::check_user_watermark(count)?;
228.         proof! {
229.             lemma_manager_attached(self);
230.             assert(self@ == g_old);
231.             assert(g_old.user_alloc_ok(count as nat));
232.             lemma_user_bulk_base(g_old, frames@);
233.         }
234. 
235.         #[cfg_attr(verus_keep_ghost, verus_spec(
236.             invariant
237.                 g_old == old(self)@,
238.                 g_old.wf(),
239.                 self@.wf(),
240.                 frames@.len() == i,
241.                 user_bulk_inv(g_old, self@, frames@),
242.                 count > 0 ==> g_old.user_alloc_ok(count as nat),
243.         ))]
244.         for i in 0..count {
245.             proof_decl! {
246.                 let ghost mview_pre = self@;
247.             }
248.             match self.upool.alloc() {
249.                 Ok(frame) => {
250.                     proof! {
251.                         lemma_user_bulk_step(g_old, mview_pre, frames@, frame);
252.                     }
253.                     frames.push(frame);
254.                 },
255.                 Err(error) => {
256.                     frames.clear();
257.                     proof! {
258.                         lemma_user_bulk_err_restored(self, g_old);
259.                     }
260.                     return Err(error);
261.                 },
262.             }
263.         }
264.         Ok(())
265.     }
266. 
267.     ///
268.     /// # Description
269.     ///
270.     /// Allocates a single user frame, applying the same kernel watermark check as
271.     /// [`Self::alloc_many_user_frames`]. This is the single-frame fast path used on
272.     /// hot paths such as copy-on-write fault resolution, where allocating an
273.     /// intermediate [`Vec`] would be wasteful.
274.     ///
275.     /// # Returns
276.     ///
277.     /// Upon success, a [`UserFrame`] is returned. Upon failure, an error is returned
278.     /// instead.
279.     ///
280.     #[verus_spec(result =>
281.         requires
282.             self.inv(),
283.         ensures
284.             final(self).inv(),
285.             match result {
286.                 Ok(uf) => {
287.                     &&& old(self)@.user_alloc_ok(1)
288.                     &&& old(self)@.free_frames.contains(uf@)
289.                     &&& final(self)@ == old(self)@.alloc_one(uf@)
290.                 },
291.                 Err(_) => {
292.                     &&& final(self)@ == old(self)@
293.                     &&& !old(self)@.user_alloc_ok(1)
294.                 },
295.             },
296.     )]
297.     pub fn alloc_user_frame(&mut self) -> Result<UserFrame, Error> {
298.         proof! {
299.             lemma_manager_attached(self);
300.         }
301.         Self::check_user_watermark(1)?;
302.         self.upool.alloc()
303.     }
304. 
305.     ///
306.     /// # Description
307.     ///
308.     /// Rejects user allocations of `count` frames that would breach the kernel
309.     /// watermark, i.e. that would drop the number of free frames below
310.     /// [`config::kernel::KERNEL_WATERMARK`].
311.     ///
312.     /// # Parameters
313.     ///
314.     /// - `count`: Number of user frames the caller intends to allocate.
315.     ///
316.     /// # Returns
317.     ///
318.     /// Upon success, `Ok(())` is returned. Upon failure, an error is returned instead.
319.     ///
320.     #[verus_spec(result =>
321.         ensures
322.             match result {
323.                 Ok(()) => crate::mm::phys::phys_view().frames.free_count()
324.                     >= count as nat + spec_kernel_watermark(),
325.                 Err(_) => crate::mm::phys::phys_view().frames.free_count()
326.                     < count as nat + spec_kernel_watermark(),
327.             },
328.     )]
329.     fn check_user_watermark(count: usize) -> Result<(), Error> {
330.         // Reading the free count first pins the abstract `free_count()` to a concrete `usize`,
331.         // hence `free_count() <= usize::MAX`. This bound is what the overflow arm below relies on
332.         // (a `kernel_watermark() + count` overflow means the threshold exceeds any possible free
333.         // count). Binding it here makes that fact available on every path without an axiom.
334.         let available: usize = frame::free_count();
335.         let watermark_threshold: usize = kernel_watermark()
336.             .checked_add(count)
337.             .ok_or_else(|| {
338.                 let reason: &str = "watermark + count overflow";
339.                 #[cfg(not(verus_keep_ghost))]
340.                 error!("{reason}");
341.                 Error::new(ErrorCode::InvalidArgument, reason)
342.             })?;
343.         if available < watermark_threshold {
344.             let reason: &str = "would breach kernel watermark";
345.             #[cfg(not(verus_keep_ghost))]
346.             error!("{reason}");
347.             return Err(Error::new(ErrorCode::OutOfMemory, reason));
348.         }
349.         Ok(())
350.     }
351. 
352.     ///
353.     /// # Description
354.     ///
355.     /// Allocates a kernel frame.
356.     ///
357.     /// Kernel allocations bypass the watermark — no artificial ceiling.
358.     ///
359.     /// # Return Values
360.     ///
361.     /// Upon success, a kernel frame is returned. Upon failure, an error is returned instead.
362.     ///
363.     #[verus_spec(result =>
364.         requires
365.             self.inv(),
366.         ensures
367.             final(self).inv(),
368.             match result {
369.                 Ok(kf) => {
370.                     &&& old(self)@.free_frames.contains(kf@)
371.                     &&& final(self)@ == old(self)@.alloc_one(kf@)
372.                 },
373.                 Err(_) => final(self)@ == old(self)@,
374.             },
375.     )]
376.     pub fn alloc_kernel_frame(&mut self) -> Result<KernelFrame, Error> {
377.         proof_decl! {
378.             let ghost g_old = self@;
379.         }
380.         let frame_addr: FrameAddress = frame::alloc()?;
381.         let result: Result<KernelFrame, Error> = KernelFrame::new(frame_addr).inspect_err(|e| {
382.             #[cfg(not(verus_keep_ghost))]
383.             warn!("failed to wrap frame after KernelFrame::new failure: {e:?}");
384.             if let Err(free_err) = frame::free(frame_addr) {
385.                 #[cfg(not(verus_keep_ghost))]
386.                 warn!("failed to free frame after KernelFrame::new failure: {free_err:?}");
387.             }
388.         });
389.         proof! {
390.             if result is Ok {
391.                 lemma_kernel_alloc_one(g_old, self@, result->Ok_0@);
392.             }
393.         }
394.         result
395.     }
396. 
397.     ///
398.     /// # Description
399.     ///
400.     /// Allocates a contiguous range of kernel frames into caller-provided storage.
401.     ///
402.     /// Kernel stacks require physically contiguous frames because the kernel uses identity
403.     /// mapping and the hardware stack pointer traverses the region linearly.
404.     /// Kernel allocations bypass the watermark — no artificial ceiling.
405.     ///
406.     /// # Parameters
407.     ///
408.     /// - `count`: Number of frames to allocate.
409.     /// - `frames`: Mutable reference to a pre-allocated vector into which to store
410.     ///   those frames' addresses.
411.     ///
412.     /// # Return Values
413.     ///
414.     /// Upon success, `Ok(())` is returned and `frames` is filled with `count`
415.     /// contiguous entries. Upon failure, an error is returned instead.
416.     ///
417.     #[verus_spec(result =>
418.         requires
419.             self.inv(),
420.             old(frames)@.len() == 0,
421.             count > 0,
422.         ensures
423.             final(self).inv(),
424.             match result {
425.                 Ok(()) => {
426.                     &&& final(frames)@.len() == count
427.                     &&& kernel_frames_contiguous(final(frames)@, count as nat)
428.                     &&& old(self)@.all_free(kernel_addr_set(final(frames)@))
429.                     &&& final(self)@ == old(self)@.book_all(kernel_addr_set(final(frames)@))
430.                 },
431.                 Err(_) => {
432.                     &&& final(self)@ == old(self)@
433.                     &&& final(frames)@.len() == 0
434.                 },
435.             },
436.     )]
437.     pub fn alloc_many_kernel_frames(
438.         &mut self,
439.         count: usize,
440.         frames: &mut Vec<KernelFrame>,
441.     ) -> Result<(), Error> {
442.         proof_decl! {
443.             let ghost g_old = self@;
444.         }
445.         proof! {
446.             assert(g_old == old(self)@);
447.             assert(g_old.wf());
448.         }
449.         // Check if caller-provided vector is not empty.
450.         if !frames.is_empty() {
451.             let reason: &str = "frames vector is not empty";
452.             #[cfg(not(verus_keep_ghost))]
453.             error!("{reason}");
454.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
455.         }
456.         if frames.capacity() < count {
457.             let reason: &str = "frames vector has insufficient capacity";
458.             #[cfg(not(verus_keep_ghost))]
459.             error!("{reason}");
460.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
461.         }
462. 
463.         let base_addr: FrameAddress = frame::alloc_contiguous(count)?;
464.         let base_raw: usize = base_addr.into_raw_value();
465.         #[cfg_attr(verus_keep_ghost, verus_spec(
466.             invariant
467.                 g_old == old(self)@,
468.                 g_old.wf(),
469.                 self@ == g_old,
470.                 base_raw as int == base_addr@,
471.                 base_raw as int + (count as int) * spec_page_size() <= usize::MAX as int,
472.         ))]
473.         for i in 0..count {
474.             proof! {
475.                 lemma_contig_no_overflow(base_raw, i, count);
476.             }
477.             let raw_addr: usize = base_raw + i * mem::PAGE_SIZE;
478.             match FrameAddress::from_raw_value(raw_addr).and_then(KernelFrame::new) {
479.                 Ok(kf) => frames.push(kf),
480.                 Err(e) => {
481.                     // Drop already-wrapped frames (frees them via KernelFrame::Drop).
482.                     frames.clear();
483.                     // Free remaining un-wrapped frames from the contiguous allocation.
484.                     #[cfg_attr(verus_keep_ghost, verus_spec(
485.                         invariant
486.                             g_old == old(self)@,
487.                             g_old.wf(),
488.                             self@ == g_old,
489.                             base_raw as int == base_addr@,
490.                             base_raw as int + (count as int) * spec_page_size()
491.                                 <= usize::MAX as int,
492.                     ))]
493.                     for j in i..count {
494.                         proof! {
495.                             lemma_contig_no_overflow(base_raw, j, count);
496.                         }
497.                         let leak_raw: usize = base_raw + j * mem::PAGE_SIZE;
498.                         if let Ok(fa) = FrameAddress::from_raw_value(leak_raw) {
499.                             if let Err(e) = frame::free(fa) {
500.                                 #[cfg(not(verus_keep_ghost))]
501.                                 warn!("failed to free leaked frame {fa:?}: {e:?}");
502.                             }
503.                         }
504.                     }
505.                     return Err(e);
506.                 },
507.             }
508.         }
509.         proof! {
510.             lemma_kernel_alloc_contiguous(g_old, self@, frames@, count as nat);
511.         }
512.         Ok(())
513.     }
514. }
515. 
516. //==================================================================================================
517. // Build-time constant accessors
518. //==================================================================================================
519. 
520. // External-bottom trust boundary: `config::kernel::KERNEL_WATERMARK` is generated by the `config`
521. // crate's `build.rs` (from `kernel_config.toml`) and lives in a non-Verus dependency crate, so
522. // Verus cannot resolve its value. This accessor ties the runtime constant to the abstract
523. // `spec_kernel_watermark()`. Listed in `verus-ai-logs/tcb-allowed.md`.
524. #[verus_verify(external_body)]
525. #[verus_spec(ret =>
526.     ensures
527.         ret as nat == spec_kernel_watermark(),
528. )]
529. fn kernel_watermark() -> usize {
530.     config::kernel::KERNEL_WATERMARK
531. }
532.

